record.field:
for lead in records:
    if not lead.x_proposal_entered_on:
        lead.write({'x_proposal_entered_on': datetime.datetime.now()})

todo = env.ref('mail.mail_activity_data_todo')

for lead in records:
    if lead.x_nurture_state in ('pending', 'generated', 'sent'):
        lead.write({'x_nurture_state': 'stopped'})
        activities = env['mail.activity'].search([
            ('res_model', '=', 'crm.lead'),
            ('res_id', '=', lead.id),
            ('activity_type_id', '=', todo.id),
        ])
        if activities:
            activities.action_feedback(feedback='Nurture campaign stopped.')

